static struct { int64_t rc, len; char d[1430]; } br_s574 = {-1, 1429, "# The prelude: visible in every module without an import.\n\nenum Option[T]:\n    Some(value: T)\n    None\n\n    fn is_some(self) -> bool:\n        match self:\n            case Some(_):\n                return true\n            case None:\n                return false\n\n    fn is_none(self) -> bool:\n        return not self.is_some()\n\n    fn unwrap(self) -> T:\n        match self:\n            case Some(v):\n                return v\n            case None:\n                panic(\"unwrap() called on None\")\n\n    fn unwrap_or(self, default: T) -> T:\n        match self:\n            case Some(v):\n                return v\n            case None:\n                return default\n\nenum Result[T, E]:\n    Ok(value: T)\n    Err(error: E)\n\n    fn is_ok(self) -> bool:\n        match self:\n            case Ok(_):\n                return true\n            case Err(_):\n                return false\n\n    fn is_err(self) -> bool:\n        return not self.is_ok()\n\n    fn unwrap(self) -> T:\n        match self:\n            case Ok(v):\n                return v\n            case Err(_):\n                panic(\"unwrap() called on Err\")\n\n    fn unwrap_or(self, default: T) -> T:\n        match self:\n            case Ok(v):\n                return v\n            case Err(_):\n                return default\n\n    fn ok(self) -> Option[T]:\n        match self:\n            case Ok(v):\n                return Some(v)\n            case Err(_):\n                return None\n"};
