static struct { int64_t rc, len; char d[25]; } br_s906 = {-1, 24, "`ref` mismatch at a call"};
static struct { int64_t rc, len; char d[73]; } br_s907 = {-1, 72, "Parameters are read-only. To change a local copy, declare the parameter\n"};
