static struct { int64_t rc, len; char d[66]; } br_s917 = {-1, 65, "Only variables, their fields and their elements can be assigned:\n"};
static struct { int64_t rc, len; char d[34]; } br_s918 = {-1, 33, "`x = 1`, `p.x = 1`, `xs[i] = 1`.\n"};
static struct { int64_t rc, len; char d[75]; } br_s919 = {-1, 74, "References are made with `let r = ref x`, where `x` is a variable. `r` is\n"};
