static struct { int64_t rc, len; char d[59]; } br_s928 = {-1, 58, "    print(xs, xs.pop())         # error: read and changed\n"};
static struct { int64_t rc, len; char d[56]; } br_s929 = {-1, 55, "    print(xs.pop(), xs.pop())   # error: changed twice\n"};
