static struct { int64_t rc, len; char d[55]; } br_s944 = {-1, 54, "a variable is changed and used again in one expression"};
static struct { int64_t rc, len; char d[80]; } br_s945 = {-1, 79, "`x\?` unwraps an `Option` or a `Result`: it gives the value inside `Some`/`Ok`,\n"};
