static struct { int64_t rc, len; char d[74]; } br_s985 = {-1, 73, "Iterations of `par` code run at the same time. To rule out data races, a\n"};
static struct { int64_t rc, len; char d[74]; } br_s986 = {-1, 73, "`par` body may not assign variables from outside it, call functions that\n"};
static struct { int64_t rc, len; char d[74]; } br_s987 = {-1, 73, "mutate them, or push/pop them. The one exception: in `par for i in ...`,\n"};
static struct { int64_t rc, len; char d[50]; } br_s988 = {-1, 49, "arrays from outside may be written at index `i`:\n"};
static struct { int64_t rc, len; char d[25]; } br_s989 = {-1, 24, "    var out = [0.0] * n\n"};
static struct { int64_t rc, len; char d[24]; } br_s990 = {-1, 23, "    par for i in 0..n:\n"};
static struct { int64_t rc, len; char d[71]; } br_s991 = {-1, 70, "        out[i] = f(i)        # OK: each iteration writes its own slot\n"};
static struct { int64_t rc, len; char d[77]; } br_s992 = {-1, 76, "To combine results, use a reduction instead: `par sum(f(i) for i in 0..n)`.\n"};
static struct { int64_t rc, len; char d[6]; } br_s993 = {-1, 5, "E0501"};
static struct { int64_t rc, len; char d[30]; } br_s994 = {-1, 29, "writing shared state in `par`"};
static struct { int64_t rc, len; char d[73]; } br_s995 = {-1, 72, "An array written as `out[i]` inside a `par for` may only be accessed as\n"};
