static struct { int64_t rc, len; char d[72]; } br_s997 = {-1, 71, "any other index might belong to an iteration running at the same time.\n"};
static struct { int64_t rc, len; char d[6]; } br_s998 = {-1, 5, "E0502"};
static struct { int64_t rc, len; char d[35]; } br_s999 = {-1, 34, "par write array accessed elsewhere"};
static struct { int64_t rc, len; char d[77]; } br_s1000 = {-1, 76, "`exit` and `world` communication would be non-deterministic inside parallel\n"};
static struct { int64_t rc, len; char d[75]; } br_s1001 = {-1, 74, "code, and so would `write_file`, `run` and the `os` functions that change\n"};
