static struct { int64_t rc, len; char d[22]; } br_s1015 = {-1, 21, "unsupported invariant"};
static struct { int64_t rc, len; char d[77]; } br_s1016 = {-1, 76, "Parallel comprehensions need a known output size. Filter afterwards, or use\n"};
