static struct { int64_t rc, len; char d[75]; } br_s1020 = {-1, 74, "`world` communication is collective: every rank takes part in every call,\n"};
static struct { int64_t rc, len; char d[78]; } br_s1021 = {-1, 77, "and all ranks must make the same calls in the same order. If some ranks skip\n"};
static struct { int64_t rc, len; char d[78]; } br_s1022 = {-1, 77, "a call that others make, the others would wait forever. brine rules this out\n"};
static struct { int64_t rc, len; char d[18]; } br_s1023 = {-1, 17, "at compile time.\n"};
static struct { int64_t rc, len; char d[75]; } br_s1024 = {-1, 74, "A call is rejected when the condition that leads to it may differ between\n"};
static struct { int64_t rc, len; char d[79]; } br_s1025 = {-1, 78, "ranks: anything computed from `world.rank()`, `clock()`, values received with\n"};
static struct { int64_t rc, len; char d[74]; } br_s1026 = {-1, 73, "`world.shift`/`world.exchange`, files, processes, `os` functions (except\n"};
static struct { int64_t rc, len; char d[75]; } br_s1027 = {-1, 74, "`os.name()` and `os.arch()`), or C functions. Early `return`, `break` and\n"};
static struct { int64_t rc, len; char d[64]; } br_s1028 = {-1, 63, "`continue` under such a condition count too, as do `and`/`or`.\n"};
static struct { int64_t rc, len; char d[27]; } br_s1029 = {-1, 26, "    if world.rank() == 0:\n"};
static struct { int64_t rc, len; char d[65]; } br_s1030 = {-1, 64, "        world.barrier()          # error: only rank 0 gets here\n"};
static struct { int64_t rc, len; char d[71]; } br_s1031 = {-1, 70, "Compute the rank-specific part first, then communicate on every rank:\n"};
