static struct { int64_t rc, len; char d[6]; } br_s1044 = {-1, 5, "E0511"};
static struct { int64_t rc, len; char d[37]; } br_s1045 = {-1, 36, "value must be the same on every rank"};
static struct { int64_t rc, len; char d[76]; } br_s1046 = {-1, 75, "brine has no unmatched `send`/`recv`, because a receive without a matching\n"};
static struct { int64_t rc, len; char d[64]; } br_s1047 = {-1, 63, "send hangs forever. Every communication is collective instead:\n"};
static struct { int64_t rc, len; char d[89]; } br_s1048 = {-1, 88, "    world.shift(v, 1)        # send v to rank + 1, receive from rank - 1 (wraps around)\n"};
static struct { int64_t rc, len; char d[86]; } br_s1049 = {-1, 85, "    world.exchange(xs)       # send xs[j] to rank j; returns what each rank sent you\n"};
static struct { int64_t rc, len; char d[59]; } br_s1050 = {-1, 58, "    world.broadcast(root, v) # everyone gets root's value\n"};
static struct { int64_t rc, len; char d[82]; } br_s1051 = {-1, 81, "    world.gather_all(v)      # everyone gets [v from rank 0, v from rank 1, ...]\n"};
static struct { int64_t rc, len; char d[50]; } br_s1052 = {-1, 49, "For example, \"rank 0 sends a message to rank 1\":\n"};
static struct { int64_t rc, len; char d[38]; } br_s1053 = {-1, 37, "    var outbox = [\"\"] * world.size()\n"};
static struct { int64_t rc, len; char d[48]; } br_s1054 = {-1, 47, "    if world.rank() == 0 and world.size() > 1:\n"};
static struct { int64_t rc, len; char d[29]; } br_s1055 = {-1, 28, "        outbox[1] = \"hello\"\n"};
static struct { int64_t rc, len; char d[40]; } br_s1056 = {-1, 39, "    let inbox = world.exchange(outbox)\n"};
static struct { int64_t rc, len; char d[38]; } br_s1057 = {-1, 37, "    # on rank 1, inbox[0] == \"hello\"\n"};
static struct { int64_t rc, len; char d[6]; } br_s1058 = {-1, 5, "E0512"};
static struct { int64_t rc, len; char d[17]; } br_s1059 = {-1, 16, "no `send`/`recv`"};
static struct { int64_t rc, len; char d[76]; } br_s1060 = {-1, 75, "The function's `requires` clause must hold at every call, and the compiler\n"};
static struct { int64_t rc, len; char d[78]; } br_s1061 = {-1, 77, "must be able to prove it from what it knows at the call site. Rules can't be\n"};
static struct { int64_t rc, len; char d[64]; } br_s1062 = {-1, 63, "broken, so an unproven claim is an error, not a runtime check.\n"};
static struct { int64_t rc, len; char d[62]; } br_s1063 = {-1, 61, "Fix it by giving the prover the facts it needs, for example:\n"};
static struct { int64_t rc, len; char d[75]; } br_s1064 = {-1, 74, "    if 0 <= i and i < len(xs):     # the call is only made when it's safe\n"};
static struct { int64_t rc, len; char d[27]; } br_s1065 = {-1, 26, "        print(get(xs, i))\n"};
static struct { int64_t rc, len; char d[83]; } br_s1066 = {-1, 82, "    assert 0 <= i < len(xs)        # checked at runtime, then known to the prover\n"};
static struct { int64_t rc, len; char d[23]; } br_s1067 = {-1, 22, "    print(get(xs, i))\n"};
static struct { int64_t rc, len; char d[79]; } br_s1068 = {-1, 78, "or by adding a `requires` to the calling function, which moves the obligation\n"};
static struct { int64_t rc, len; char d[76]; } br_s1069 = {-1, 75, "to its callers. The error lists the facts the prover knew and the claim it\n"};
static struct { int64_t rc, len; char d[9]; } br_s1070 = {-1, 8, "needed.\n"};
static struct { int64_t rc, len; char d[24]; } br_s1071 = {-1, 23, "precondition not proven"};
static struct { int64_t rc, len; char d[75]; } br_s1072 = {-1, 74, "An `ensures` clause must hold on every `return`. The prover reasons about\n"};
static struct { int64_t rc, len; char d[74]; } br_s1073 = {-1, 73, "each path through the function. If it can't show the claim on some path,\n"};
static struct { int64_t rc, len; char d[75]; } br_s1074 = {-1, 74, "add a `requires` the claim depends on, an `invariant` to loops before the\n"};
static struct { int64_t rc, len; char d[59]; } br_s1075 = {-1, 58, "return, or an `assert` (runtime check) before the return.\n"};
static struct { int64_t rc, len; char d[25]; } br_s1076 = {-1, 24, "postcondition not proven"};
static struct { int64_t rc, len; char d[78]; } br_s1077 = {-1, 77, "A loop `invariant` must hold before the first iteration. For `for i in a..b`\n"};
static struct { int64_t rc, len; char d[75]; } br_s1078 = {-1, 74, "loops, invariants may mention `i`; on entry they're checked with `i = a`.\n"};
static struct { int64_t rc, len; char d[71]; } br_s1079 = {-1, 70, "Initialize variables so the invariant holds, or weaken the invariant.\n"};
static struct { int64_t rc, len; char d[25]; } br_s1080 = {-1, 24, "invariant false on entry"};
static struct { int64_t rc, len; char d[68]; } br_s1081 = {-1, 67, "Assuming the invariant (and the loop condition) at the start of an\n"};
static struct { int64_t rc, len; char d[68]; } br_s1082 = {-1, 67, "iteration, the prover couldn't show it holds again at the end. For\n"};
static struct { int64_t rc, len; char d[76]; } br_s1083 = {-1, 75, "`for i in a..b`, the invariant is checked at the end of the iteration with\n"};
static struct { int64_t rc, len; char d[10]; } br_s1084 = {-1, 9, "`i + 1`.\n"};
static struct { int64_t rc, len; char d[72]; } br_s1085 = {-1, 71, "The prover only knows what the invariant says about variables the loop\n"};
static struct { int64_t rc, len; char d[74]; } br_s1086 = {-1, 73, "changes, so invariants often need to carry bounds such as `0 <= i <= n`.\n"};
static struct { int64_t rc, len; char d[24]; } br_s1087 = {-1, 23, "invariant not preserved"};
static struct { int64_t rc, len; char d[78]; } br_s1088 = {-1, 77, "`prove e` asks the compiler to show `e` is always true at that point. Unlike\n"};
static struct { int64_t rc, len; char d[78]; } br_s1089 = {-1, 77, "`assert`, it generates no runtime code, so it must be provable. Use `assert`\n"};
static struct { int64_t rc, len; char d[35]; } br_s1090 = {-1, 34, "if a runtime check is acceptable.\n"};
static struct { int64_t rc, len; char d[17]; } br_s1091 = {-1, 16, "claim not proven"};
static struct { int64_t rc, len; char d[74]; } br_s1092 = {-1, 73, "Contracts (`requires`, `ensures`, `invariant`, `prove`) are pure logical\n"};
static struct { int64_t rc, len; char d[76]; } br_s1093 = {-1, 75, "statements. They may use arithmetic, comparisons, `and`/`or`/`not`, `len`,\n"};
static struct { int64_t rc, len; char d[80]; } br_s1094 = {-1, 79, "`abs`, `min`, `max`, fields, indexing, constants, and `result` (in `ensures`).\n"};
static struct { int64_t rc, len; char d[55]; } br_s1095 = {-1, 54, "Function calls and other side effects aren't allowed.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1096 = {-1, 5, "E0606"};
static struct { int64_t rc, len; char d[31]; } br_s1097 = {-1, 30, "not allowed in a specification"};
static struct { int64_t rc, len; char d[73]; } br_s1098 = {-1, 72, "`import a.b` loads `a/b.br` relative to the directory of the main file.\n"};
static struct { int64_t rc, len; char d[35]; } br_s1099 = {-1, 34, "Check the file name and location.\n"};
static struct { int64_t rc, len; char d[17]; } br_s1100 = {-1, 16, "module not found"};
static struct { int64_t rc, len; char d[72]; } br_s1101 = {-1, 71, "brine compiles to C and then uses the system C compiler (clang or gcc)\n"};
static struct { int64_t rc, len; char d[71]; } br_s1102 = {-1, 70, "to produce a native executable. Install one, or point BRINE_CC at it.\n"};
static struct { int64_t rc, len; char d[35]; } br_s1103 = {-1, 34, "`brine doctor` checks your setup.\n"};
static struct { int64_t rc, len; char d[14]; } br_s1104 = {-1, 13, "no C compiler"};
static struct { int64_t rc, len; char d[78]; } br_s1105 = {-1, 77, "A program starts at `fn main():` in its main file. `main` may also return an\n"};
static struct { int64_t rc, len; char d[76]; } br_s1106 = {-1, 75, "`int`, which becomes the process exit code. (Libraries and test-only files\n"};
static struct { int64_t rc, len; char d[66]; } br_s1107 = {-1, 65, "can be checked with `brine check` and tested with `brine test`.)\n"};
static struct { int64_t rc, len; char d[17]; } br_s1108 = {-1, 16, "no main function"};
static struct { int64_t rc, len; char d[76]; } br_s1109 = {-1, 75, "`main` takes no parameters (command-line arguments come from `args()`) and\n"};
static struct { int64_t rc, len; char d[17]; } br_s1110 = {-1, 16, "returns one of:\n"};
static struct { int64_t rc, len; char d[51]; } br_s1111 = {-1, 50, "    fn main():                      # exit code 0\n"};
static struct { int64_t rc, len; char d[53]; } br_s1112 = {-1, 52, "    fn main() -> int:               # the exit code\n"};
static struct { int64_t rc, len; char d[81]; } br_s1113 = {-1, 80, "    fn main() -> Result[(), str]:   # Err(e) prints \"error: e\" and exits with 1\n"};
static struct { int64_t rc, len; char d[40]; } br_s1114 = {-1, 39, "The `Result` form lets `main` use `\?`:\n"};
static struct { int64_t rc, len; char d[35]; } br_s1115 = {-1, 34, "    fn main() -> Result[(), str]:\n"};
static struct { int64_t rc, len; char d[45]; } br_s1116 = {-1, 44, "        let text = read_file(\"config.txt\")\?\n"};
static struct { int64_t rc, len; char d[26]; } br_s1117 = {-1, 25, "        print(len(text))\n"};
static struct { int64_t rc, len; char d[23]; } br_s1118 = {-1, 22, "        return Ok(())\n"};
static struct { int64_t rc, len; char d[25]; } br_s1119 = {-1, 24, "invalid `main` signature"};
static struct { int64_t rc, len; char d[75]; } br_s1120 = {-1, 74, "`embed(path)` puts a file's text into the program when it is compiled, so\n"};
static struct { int64_t rc, len; char d[80]; } br_s1121 = {-1, 79, "the file must exist then, be UTF-8 text, and its path must be a string literal\n"};
static struct { int64_t rc, len; char d[79]; } br_s1122 = {-1, 78, "(not a variable or an f-string). The path is relative to the directory of the\n"};
static struct { int64_t rc, len; char d[69]; } br_s1123 = {-1, 68, "`.br` file that contains the call; \"\\r\\n\" line endings become \"\\n\".\n"};
static struct { int64_t rc, len; char d[70]; } br_s1124 = {-1, 69, "    const HELP = embed(\"help.txt\")      # help.txt next to this file\n"};
static struct { int64_t rc, len; char d[21]; } br_s1125 = {-1, 20, "        print(HELP)\n"};
static struct { int64_t rc, len; char d[71]; } br_s1126 = {-1, 70, "To read a file while the program runs instead, use `read_file(path)`.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1127 = {-1, 5, "E0707"};
static struct { int64_t rc, len; char d[20]; } br_s1128 = {-1, 19, "cannot embed a file"};
static struct { int64_t rc, len; char d[75]; } br_s1129 = {-1, 74, "The compiler couldn't create its output or cache files. Check permissions\n"};
static struct { int64_t rc, len; char d[50]; } br_s1130 = {-1, 49, "and free disk space for the `target/` directory.\n"};
static struct { int64_t rc, len; char d[25]; } br_s1131 = {-1, 24, "cannot write build files"};
static struct { int64_t rc, len; char d[73]; } br_s1132 = {-1, 72, "The generated C code didn't compile. That's a bug in brine, not in your\n"};
static struct { int64_t rc, len; char d[66]; } br_s1133 = {-1, 65, "program. Please report it with the source file and the output of\n"};
static struct { int64_t rc, len; char d[17]; } br_s1134 = {-1, 16, "`brine doctor`.\n"};
static struct { int64_t rc, len; char d[18]; } br_s1135 = {-1, 17, "C compiler failed"};
static struct { int64_t rc, len; char d[75]; } br_s1136 = {-1, 74, "Every `match` must handle every possible value, so a new enum variant can\n"};
static struct { int64_t rc, len; char d[77]; } br_s1137 = {-1, 76, "never slip through unnoticed. The error shows an example value that no case\n"};
static struct { int64_t rc, len; char d[54]; } br_s1138 = {-1, 53, "handles. Add a case for it, or end with a catch-all:\n"};
static struct { int64_t rc, len; char d[33]; } br_s1139 = {-1, 32, "            return 3.14 * r * r\n"};
static struct { int64_t rc, len; char d[24]; } br_s1140 = {-1, 23, "            return 0.0\n"};
static struct { int64_t rc, len; char d[76]; } br_s1141 = {-1, 75, "Cases with an `if` guard don't count toward this, because the guard may be\n"};
static struct { int64_t rc, len; char d[79]; } br_s1142 = {-1, 78, "false. Integers and strings have too many values to list, so matching on them\n"};
static struct { int64_t rc, len; char d[74]; } br_s1143 = {-1, 73, "always needs `case _:` (or a plain name, which also matches everything).\n"};
static struct { int64_t rc, len; char d[6]; } br_s1144 = {-1, 5, "E0320"};
static struct { int64_t rc, len; char d[35]; } br_s1145 = {-1, 34, "`match` doesn't handle every value"};
static struct { int64_t rc, len; char d[76]; } br_s1146 = {-1, 75, "In `case A | B:` either alternative may match, so a name bound in only one\n"};
static struct { int64_t rc, len; char d[73]; } br_s1147 = {-1, 72, "of them might not have a value. Use `_` inside `|` patterns, or write a\n"};
static struct { int64_t rc, len; char d[39]; } br_s1148 = {-1, 38, "separate `case` for each alternative.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1149 = {-1, 5, "E0321"};
static struct { int64_t rc, len; char d[23]; } br_s1150 = {-1, 22, "names bound inside `|`"};
static struct { int64_t rc, len; char d[78]; } br_s1151 = {-1, 77, "A plain name in a pattern always captures the matched value under that name;\n"};
static struct { int64_t rc, len; char d[77]; } br_s1152 = {-1, 76, "it doesn't compare against a constant of the same name. Compare explicitly:\n"};
static struct { int64_t rc, len; char d[14]; } br_s1153 = {-1, 13, "    match n:\n"};
static struct { int64_t rc, len; char d[31]; } br_s1154 = {-1, 30, "        case x if x == LIMIT:\n"};
static struct { int64_t rc, len; char d[17]; } br_s1155 = {-1, 16, "            ...\n"};
static struct { int64_t rc, len; char d[6]; } br_s1156 = {-1, 5, "E0322"};
static struct { int64_t rc, len; char d[27]; } br_s1157 = {-1, 26, "constant used as a pattern"};
static struct { int64_t rc, len; char d[73]; } br_s1158 = {-1, 72, "A method can have type parameters of its own, and a method of a generic\n"};
static struct { int64_t rc, len; char d[76]; } br_s1159 = {-1, 75, "type can also use the type's parameters. The two can't share a name, since\n"};
static struct { int64_t rc, len; char d[51]; } br_s1160 = {-1, 50, "`T` would then mean two things inside the method:\n"};
static struct { int64_t rc, len; char d[20]; } br_s1161 = {-1, 19, "    struct Box[T]:\n"};
static struct { int64_t rc, len; char d[14]; } br_s1162 = {-1, 13, "        v: T\n"};
static struct { int64_t rc, len; char d[76]; } br_s1163 = {-1, 75, "        fn pair[T](self, x: T) -> (T, T):    # error: `T` is already Box's\n"};
static struct { int64_t rc, len; char d[51]; } br_s1164 = {-1, 50, "        fn pair[U](self, x: U) -> (T, U):    # ok\n"};
static struct { int64_t rc, len; char d[32]; } br_s1165 = {-1, 31, "            return (self.v, x)\n"};
static struct { int64_t rc, len; char d[78]; } br_s1166 = {-1, 77, "Type arguments of a method are inferred from its arguments, or written after\n"};
static struct { int64_t rc, len; char d[38]; } br_s1167 = {-1, 37, "the method name: `b.pair[str](\"x\")`.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1168 = {-1, 5, "E0331"};
static struct { int64_t rc, len; char d[45]; } br_s1169 = {-1, 44, "a method's type parameter repeats its type's"};
static struct { int64_t rc, len; char d[76]; } br_s1170 = {-1, 75, "The compiler works out type arguments from the arguments and from the type\n"};
static struct { int64_t rc, len; char d[77]; } br_s1171 = {-1, 76, "the result must have. When neither says what a type parameter is, write it:\n"};
static struct { int64_t rc, len; char d[63]; } br_s1172 = {-1, 62, "    let xs = make[int]()             # explicit type argument\n"};
static struct { int64_t rc, len; char d[65]; } br_s1173 = {-1, 64, "    let o: Option[str] = None        # or annotate the variable\n"};
static struct { int64_t rc, len; char d[40]; } br_s1174 = {-1, 39, "    let p = Pair[int, str](a=1, b=\"x\")\n"};
static struct { int64_t rc, len; char d[6]; } br_s1175 = {-1, 5, "E0332"};
static struct { int64_t rc, len; char d[28]; } br_s1176 = {-1, 27, "can't infer a type argument"};
static struct { int64_t rc, len; char d[80]; } br_s1177 = {-1, 79, "Each combination of type arguments makes a separate copy of a generic function\n"};
static struct { int64_t rc, len; char d[79]; } br_s1178 = {-1, 78, "or type. A function that calls itself with an ever larger type, like `f[[T]]`\n"};
static struct { int64_t rc, len; char d[77]; } br_s1179 = {-1, 76, "inside `f[T]`, would need infinitely many. Restructure the recursion so the\n"};
static struct { int64_t rc, len; char d[31]; } br_s1180 = {-1, 30, "type arguments stay the same.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1181 = {-1, 5, "E0333"};
static struct { int64_t rc, len; char d[27]; } br_s1182 = {-1, 26, "too many generic instances"};
static struct { int64_t rc, len; char d[68]; } br_s1183 = {-1, 67, "Generic types need one type argument per parameter: `Option[int]`,\n"};
static struct { int64_t rc, len; char d[72]; } br_s1184 = {-1, 71, "`Result[int, str]`, `Pair[A, B]`. Types that aren't generic take none.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1185 = {-1, 5, "E0334"};
static struct { int64_t rc, len; char d[21]; } br_s1186 = {-1, 20, "wrong type arguments"};
static struct { int64_t rc, len; char d[72]; } br_s1187 = {-1, 71, "Map keys must be compared with `==` reliably, so they can be integers,\n"};
static struct { int64_t rc, len; char d[68]; } br_s1188 = {-1, 67, "`bool`, `str`, enums, or arrays, tuples and structs made of those.\n"};
static struct { int64_t rc, len; char d[73]; } br_s1189 = {-1, 72, "Floats are not allowed because `nan != nan`; maps can't be keys either.\n"};
static struct { int64_t rc, len; char d[45]; } br_s1190 = {-1, 44, "    var by_id: {int: str} = {}         # ok\n"};
static struct { int64_t rc, len; char d[45]; } br_s1191 = {-1, 44, "    var cells: {(int, int): bool} = {} # ok\n"};
static struct { int64_t rc, len; char d[48]; } br_s1192 = {-1, 47, "    var bad: {float: str} = {}         # error\n"};
static struct { int64_t rc, len; char d[6]; } br_s1193 = {-1, 5, "E0335"};
