static struct { int64_t rc, len; char d[61]; } br_s1196 = {-1, 60, "first value would be silently replaced. Remove one of them.\n"};
static struct { int64_t rc, len; char d[6]; } br_s1197 = {-1, 5, "E0336"};
static struct { int64_t rc, len; char d[31]; } br_s1198 = {-1, 30, "duplicate key in a map literal"};
static struct { int64_t rc, len; char d[77]; } br_s1199 = {-1, 76, "A comparison on its own line does nothing. Did you mean `=` (assignment) or\n"};
static struct { int64_t rc, len; char d[21]; } br_s1200 = {-1, 20, "`assert` / `prove`\?\n"};
static struct { int64_t rc, len; char d[6]; } br_s1201 = {-1, 5, "W0001"};
static struct { int64_t rc, len; char d[18]; } br_s1202 = {-1, 17, "unused comparison"};
static struct { int64_t rc, len; char d[80]; } br_s1203 = {-1, 79, "An earlier `case` (`_` or a plain name, without a guard) already matches every\n"};
